<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
Auth::requireLogin(); $operator=Auth::user();
if(!$operator || (int)$operator['is_superadmin']!==1){http_response_code(403);exit('Keine Berechtigung.');}
$pdo=db(); $schema=dirname(__DIR__).'/database/migrations/005_saas_operations.sql';
foreach(array_filter(array_map('trim',explode(';',(string)file_get_contents($schema)))) as $statement){$pdo->exec($statement);}
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$st=$pdo->prepare('SELECT * FROM saas_registrations WHERE id=? AND status_name IN ("pending","verified")');$st->execute([$id]);$reg=$st->fetch();
try{
 if(!$reg) throw new RuntimeException('Registrierungsanfrage wurde nicht gefunden.');
 if($action==='reject'){$pdo->prepare('UPDATE saas_registrations SET status_name="rejected",rejection_reason=? WHERE id=?')->execute([trim((string)($_POST['reason']??''))?:'Vom Betreiber abgelehnt',$id]);flash('success','Registrierung abgelehnt.');}
 elseif($action==='approve'){
  $pdo->beginTransaction();$slugSource=function_exists('iconv')?iconv('UTF-8','ASCII//TRANSLIT',$reg['organization_name']):$reg['organization_name'];$slug=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',(string)$slugSource),'-')).'-'.bin2hex(random_bytes(2));
  $s=$pdo->prepare('INSERT INTO organizations (name,slug,city,email) VALUES (?,?,?,?)');$s->execute([$reg['organization_name'],$slug,$reg['city'],$reg['contact_email']]);$tenant=(int)$pdo->lastInsertId();
  $s=$pdo->prepare('INSERT INTO users (tenant_id,first_name,last_name,email,password_hash,role,is_superadmin) VALUES (?,?,?,?,?,"admin",0)');$s->execute([$tenant,$reg['first_name'],$reg['last_name'],$reg['contact_email'],$reg['password_hash']]);
  $plan=(int)($reg['plan_id']?:$pdo->query("SELECT id FROM saas_plans WHERE plan_key='free' LIMIT 1")->fetchColumn());$today=date('Y-m-d');$trial=date('Y-m-d',strtotime('+30 days'));
  $s=$pdo->prepare('INSERT INTO saas_subscriptions (tenant_id,plan_id,status_name,billing_cycle,starts_at,trial_ends_at,current_period_start,current_period_end) VALUES (?,?, "trial","manual",?,?,?,?,?)');$s->execute([$tenant,$plan,$today,$trial,$today,$trial]);
  $pdo->prepare('INSERT INTO saas_tenant_settings (tenant_id,display_name,support_email) VALUES (?,?,?)')->execute([$tenant,$reg['organization_name'],'support@jf-system.de']);
  $pdo->prepare('UPDATE saas_registrations SET status_name="approved",approved_at=NOW(),approved_by=? WHERE id=?')->execute([(int)$operator['id'],$id]);$pdo->commit();flash('success','Mandant wurde aus der Registrierung angelegt.');
 }
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}
header('Location: registrations.php');exit;}
$flash=pull_flash();$rows=$pdo->query("SELECT r.*,p.name AS plan_name FROM saas_registrations r LEFT JOIN saas_plans p ON p.id=r.plan_id ORDER BY r.requested_at DESC")->fetchAll();
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrierungen · JF-SYSTEM.de</title><style>:root{--navy:#102b4e;--red:#d71920;--bg:#f3f6f9;--line:#dce4ed;--muted:#66758a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#152235;font:15px/1.5 Inter,system-ui,sans-serif}.wrap{max-width:1200px;margin:36px auto;padding:0 18px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.top h1{margin:0}.back{color:var(--navy);font-weight:800;text-decoration:none}.panel{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden}.flash{padding:13px 16px;border-radius:9px;margin-bottom:16px;background:#eaf6ef;color:#0c713d}.flash.error{background:#ffe8e9;color:#a5161b}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:13px 15px;border-bottom:1px solid var(--line);white-space:nowrap}.table th{color:var(--muted);font-size:12px;text-transform:uppercase;background:#f8fafc}.pill{border-radius:999px;padding:4px 9px;font-size:12px;font-weight:800;background:#fff4df;color:#a76600}.pill.approved{background:#eaf6ef;color:#0c713d}.pill.rejected{background:#ffe8e9;color:#a5161b}.btn{border:0;border-radius:8px;padding:8px 10px;background:var(--red);color:#fff;font-weight:800;cursor:pointer}.btn.secondary{background:#edf2f7;color:var(--navy)}.actions{display:flex;gap:7px}@media(max-width:700px){.wrap{margin:18px auto}.table-wrap{overflow:auto}.top{display:block}.top a{display:inline-block;margin-top:8px}}</style></head><body><main class="wrap"><header class="top"><h1>Registrierungsanfragen</h1><a class="back" href="index.php?tab=tenants">← Zum Betreiberbereich</a></header><?php if($flash):?><div class="flash <?= $flash['type']==='error'?'error':'' ?>"><?=e($flash['message'])?></div><?php endif; ?><section class="panel"><div style="overflow:auto"><table class="table"><tr><th>Organisation</th><th>Kontakt</th><th>Tarif</th><th>Angefragt</th><th>Status</th><th>Aktionen</th></tr><?php foreach($rows as $row): ?><tr><td><strong><?=e($row['organization_name'])?></strong><br><?=e($row['city']?:'–')?></td><td><?=e($row['first_name'].' '.$row['last_name'])?><br><?=e($row['contact_email'])?></td><td><?=e($row['plan_name']?:'Free')?></td><td><?=e((new DateTimeImmutable($row['requested_at']))->format('d.m.Y H:i'))?></td><td><span class="pill <?=e($row['status_name'])?>"><?=e($row['status_name'])?></span></td><td><?php if(in_array($row['status_name'],['pending','verified'],true)): ?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="approve"><button class="btn">Freigeben</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="reject"><button class="btn secondary">Ablehnen</button></form></div><?php else: ?>–<?php endif; ?></td></tr><?php endforeach; ?></table></div></section></main></body></html>